// ❌ OLD: JavaScript must keep a mirror class in sync with the DOM.
// Every badge added/removed requires manual class updates, and any
// missed sync leaves the styling stale.
const cards = document.querySelectorAll('.card');
for (const card of cards) {
  // ❌ OLD: manual query + classList mutation per card
  if (card.querySelector('.badge')) {
    card.classList.add('has-badge');
  } else {
    card.classList.remove('has-badge');
  }
}

// Add a badge later and the class must be updated again:
card.querySelector('.badge').addEventListener('something', () => {
  card.classList.add('has-badge'); // ❌ OLD: manual resync, easy to forget
});

/* ✅ NEW: The stylesheet declares the relationship directly. No
   JavaScript, no mirror classes, no resync bugs — the engine
   re-evaluates :has() when the subtree changes. */

.card:has(.badge) {
  border-color: red; /* ✅ NEW: applies whenever a .badge is present */
}

.card:has(.badge):not(:has(.badge--new)) {
  border-style: dashed; /* ✅ NEW: combinable with :not for richer states */
}

/* Adding or removing a .badge updates the style automatically because
   the engine invalidates the :has() match on subtree mutation. */
